def unit_rank(c: str) -> int:
    match c:
        case "d":
            return 1
        case "h":
            return 2
        case "m":
            return 3
        case "s":
            return 4
        case _:
            return 0

def unit_secs(r: int) -> int:
    match r:
        case 1:
            return 86400
        case 2:
            return 3600
        case 3:
            return 60
        case _:
            return 1

def parse_duration(s: str) -> Result[int, str]:
    if s == "":
        return Err("empty")
    total = 0
    digits = ""
    last_rank = 0
    for c in split(s, ""):
        if c >= "0" and c <= "9":
            digits += c
        else:
            r = unit_rank(c)
            if r == 0:
                return Err("unknown unit: " + c)
            if digits == "":
                return Err("missing number before " + c)
            if r <= last_rank:
                return Err("unit out of order: " + c)
            total += unwrap_or(parse_int(digits), 0) * unit_secs(r)
            last_rank = r
            digits = ""
    if digits != "":
        return Err("missing unit")
    return Ok(total)

