type EditOp = Insert(text: str) | Delete(n: int) | Left(n: int) | Right(n: int) | Undo | Redo

class Editor:
    text: str
    cur: int
    history: list[tuple[str, int]]
    redo_history: list[tuple[str, int]]

def step(e: Editor, op: EditOp) -> Editor:
    cs = split(e.text, "")
    saved = append(e.history, (e.text, e.cur))
    match op:
        case Insert(t):
            return insert(e, t, saved)
        case Delete(n):
            return delete(e, min(n, e.cur), saved)
        case Left(n):
            return Editor(text=e.text, cur=max(0, e.cur - n), history=e.history, redo_history=[])
        case Right(n):
            return Editor(text=e.text, cur=min(len(cs), e.cur + n), history=e.history, redo_history=[])
        case Undo:
            return undo(e)
        case Redo:
            return redo(e)

def insert(e: Editor, t: str, saved: list[tuple[str, int]]) -> Editor:
    cs = split(e.text, "")
    text = join(take(cs, e.cur), "") + t + join(drop(cs, e.cur), "")
    return Editor(text=text, cur=e.cur + str_len(t), history=saved, redo_history=[])

