            return Editor(text=p[0], cur=p[1], history=undo_saved, redo_history=take(e.redo_history, n - 1))
        case None:
            return e

def text_editor(ops: list[EditOp]) -> str:
    start = Editor(text="", cur=0, history=[], redo_history=[])
    result = fold(ops, start, lambda e, op: step(e, op))
    return result.text
